        self.owner.put(&mut row[29..29 + 3], heap);
        row[32] = self.team;
        row[33] = self.age;
        row[34] = self.life;
        row[35] = self.health;
        match &self.gone { Some(v) => { row[36] = 0.0; row[36 + 1] = if (*v) { 1.0 } else { 0.0 }; } None => { row[36] = 2.0; row[36 + 1..36 + 2].fill(0.0); } }
